async function runTaskAction(taskId, action, trigger) {
  try {
    setButtonLoading(trigger, true, labelize(action));
    requireWallet2();
    updateStatus2("Submitting action", `Running ${labelize(action)} for this task.`, "neutral");
    if (action === "settle") {
      await sendJson2(`/api/settlements/tasks/${taskId}/settle`, "POST", { actorWallet: state.wallet });
    } else if (action === "refund") {
      await sendJson2(`/api/settlements/tasks/${taskId}/refund`, "POST", { actorWallet: state.wallet });
    } else if (action === "dispute") {
      const reason = window.prompt("Dispute reason", "Buyer disputes the current result quality and requests manual review.");
      if (!reason) {
        updateStatus2("Dispute cancelled", "A dispute reason is required.", "warn");
        return;
      }
      await sendJson2(`/api/settlements/tasks/${taskId}/dispute`, "POST", { actorWallet: state.wallet, reason });
    } else if (action === "appeal") {
      const reason = window.prompt("Appeal reason", "Buyer requests a stricter re-evaluation because the prior review outcome remains unsatisfactory.");
      if (!reason) {
        updateStatus2("Appeal cancelled", "An appeal reason is required.", "warn");
        return;
      }
      await sendJson2(`/api/task-market/tasks/${taskId}/appeal`, "POST", { actorWallet: state.wallet, reason });
    } else {
      await sendJson2(`/api/task-market/tasks/${taskId}/${action}`, "POST", { actorWallet: state.wallet });
    }
    if (action === "settle") {
      burst2("settled");
    } else if (action === "approve") {
      burst2("publish");
    }
    updateStatus2("Task updated", `${labelize(action)} completed successfully.`, action === "refund" ? "warn" : "success");
    await loadMarketData2();
    await renderTaskDetail(taskId);
  } catch (error) {
    updateStatus2("Action failed", statusMessage(error, "Action failed"), "warn");
  } finally {
    setButtonLoading(trigger, false);
  }
}
