    const submissionId = state.task?.latestSubmissionId || `${taskId}-submission`;
    const path = mode === "hybrid" ? "hybrid" : "assisted";
    updateStatus2("Evaluation running", `${labelize(mode)} is analyzing the output.`, "neutral");
