      const nextValue = ["minLatencyMs", "maxLatencyMs", "maxPayloadSize"].includes(key) ? Number(rawValue || 0) : key === "skills" ? uniqueItems(splitListInput(rawValue)) : rawValue;
      state.externalAgentForm[key] = nextValue;
